// Supabase / Lovable Cloud Edge Function for AI drafting.
// handler.js is generated by `npm run build:api` from the same code the Vercel Function uses.
//
// Set these as function secrets: AI_PROVIDER, AI_API_KEY, AI_MODEL (see .env.example),
// and AI_ALLOWED_ORIGIN with the address of the published app.
// Then set VITE_AI_ENDPOINT in the app to this function's URL.
import { createAiHandler } from "./handler.js";

declare const Deno: { env: { toObject(): Record<string, string> }; serve(handler: (request: Request) => Promise<Response>): void };

Deno.serve(createAiHandler(() => Deno.env.toObject()));
